parameters.jsCode:
// Stammdaten pruefen, bevor irgendetwas verteilt wird. Warum so streng:
// Ein falsches Eintrittsdatum verschiebt saemtliche Fristen, und eine fehlende
// Vorgesetzten-Adresse laesst die halbe Checkliste ins Leere laufen — beides faellt
// sonst erst am ersten Arbeitstag auf.
function datumLesen(wert) {
  if (!wert) return null;
  const t = String(wert).trim();
  const de = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (de) return new Date(Number(de[3]), Number(de[2]) - 1, Number(de[1]));
  const iso = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
  return null;
}

const zweiStellig = (n) => String(n).padStart(2, '0');
const datumDe = (d) => `${zweiStellig(d.getDate())}.${zweiStellig(d.getMonth() + 1)}.${d.getFullYear()}`;

const raus = [];
for (const eintrag of $input.all()) {
  // Je nach Absender liegen die Felder direkt oder unter `body` — beides zulassen.
  const d = eintrag.json.body ?? eintrag.json;

  const eintritt = datumLesen(d.eintrittsdatum);
  const fehlend = [];
  if (!d.vorname) fehlend.push('vorname');
  if (!d.nachname) fehlend.push('nachname');
  if (!eintritt) fehlend.push('eintrittsdatum (TT.MM.JJJJ)');
  if (!d.abteilung) fehlend.push('abteilung');
  if (!d.position) fehlend.push('position');
  if (!d.vorgesetzter_mail) fehlend.push('vorgesetzter_mail');
  if (!d.mail_privat) fehlend.push('mail_privat (fuer die Willkommensmail)');

  // Liegt der Eintritt in weniger als sieben Tagen, reicht der uebliche Vorlauf fuer
  // Hardware und Zugaenge nicht — das muss die IT sofort wissen.
  const heute = new Date();
  heute.setHours(0, 0, 0, 0);
  const tageBisEintritt = eintritt ? Math.round((eintritt - heute) / 86400000) : null;

  raus.push({
    json: {
      vorname: d.vorname ?? '',
      nachname: d.nachname ?? '',
      name: `${d.vorname ?? ''} ${d.nachname ?? ''}`.trim(),
      mail_privat: d.mail_privat ?? '',
      position: d.position ?? '',
      abteilung: d.abteilung ?? 'Sonstige',
      standort: d.standort ?? 'Hauptstandort',
      vorgesetzter: d.vorgesetzter ?? '',
      vorgesetzter_mail: d.vorgesetzter_mail ?? '',
      arbeitszeit: d.arbeitszeit ?? 'Vollzeit',
      homeoffice: d.homeoffice === true || d.homeoffice === 'true',
      fuehrungskraft: d.fuehrungskraft === true || d.fuehrungskraft === 'true',
      eintrittsdatum: eintritt ? datumDe(eintritt) : null,
      eintritt_iso: eintritt ? eintritt.toISOString().slice(0, 10) : null,
      tage_bis_eintritt: tageBisEintritt,
      eilfall: tageBisEintritt !== null && tageBisEintritt < 7,
      fehlende_felder: fehlend,
      stammdaten_vollstaendig: fehlend.length === 0,
      gemeldet_am: new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' })
    }
  });
}
return raus;

