parameters.jsCode:
// Baut die Checkliste: Grundpaket fuer alle, Zusatzaufgaben nach Abteilung,
// Rolle und Arbeitsform. Fristen werden als Versatz zum ersten Arbeitstag gepflegt
// (negativ = vorher), weil sich der Eintritt haeufiger verschiebt als der Ablauf.
// Zustaendigkeiten stehen an der Aufgabe, damit die Verteilung spaeter ohne
// Sonderregeln funktioniert.
const m = $input.first().json;

const VERTEILER = {
  IT: 'HIER_MAIL_IT_EINTRAGEN',
  Facility: 'HIER_MAIL_FACILITY_EINTRAGEN',
  Personal: 'HIER_MAIL_PERSONAL_EINTRAGEN',
  Buchhaltung: 'HIER_MAIL_BUCHHALTUNG_EINTRAGEN',
  Fuehrungskraft: m.vorgesetzter_mail
};

// [Kategorie, Aufgabe, Zustaendig, Versatz in Tagen zum Eintritt]
const GRUNDPAKET = [
  ['Dokumente', 'Arbeitsvertrag unterschrieben zurueckerhalten und ablegen', 'Personal', -14],
  ['Dokumente', 'Sozialversicherungsnummer, Steuer-ID und Bankverbindung erfassen', 'Buchhaltung', -10],
  ['Dokumente', 'Anmeldung bei Sozialversicherung und Berufsgenossenschaft', 'Buchhaltung', -5],
  ['IT-Zugaenge', 'Benutzerkonto, Mailadresse und Gruppenrechte anlegen', 'IT', -7],
  ['IT-Zugaenge', 'Zugriff auf Fachanwendungen der Abteilung freischalten', 'IT', -3],
  ['IT-Zugaenge', 'Mehr-Faktor-Authentifizierung einrichten und Passwortrichtlinie erklaeren', 'IT', 1],
  ['Arbeitsplatz', 'Hardware bestellen und einrichten (Notebook, Monitor, Headset)', 'IT', -10],
  ['Arbeitsplatz', 'Arbeitsplatz einrichten, Schluessel und Zutrittsausweis bereitlegen', 'Facility', -2],
  ['Arbeitsplatz', 'Spind, Arbeitskleidung und Parkplatz zuweisen', 'Facility', -2],
  ['Organisation', 'Einarbeitungsplan mit Wochenzielen erstellen', 'Fuehrungskraft', -5],
  ['Organisation', 'Patenschaft festlegen und mit der Person abstimmen', 'Fuehrungskraft', -3],
  ['Organisation', 'Begruessung am ersten Tag, Rundgang und Teamvorstellung', 'Fuehrungskraft', 0],
  ['Schulungen', 'Sicherheitsunterweisung nach DGUV Vorschrift 1 durchfuehren', 'Personal', 1],
  ['Schulungen', 'Datenschutzunterweisung und Vertraulichkeitsverpflichtung (Art. 32 DSGVO)', 'Personal', 3],
  ['Schulungen', 'KI-Kompetenzschulung nach Art. 4 EU AI Act (Grundlagen, Grenzen, Kennzeichnungspflichten, betriebliche KI-Richtlinie)', 'Personal', 30],
  ['Organisation', 'Feedbackgespraech nach der ersten Woche', 'Fuehrungskraft', 7],
  ['Organisation', 'Probezeitgespraech terminieren (nach vier Monaten)', 'Fuehrungskraft', 120]
];

const NACH_ABTEILUNG = {
  IT: [['Schulungen', 'Administrationsrechte und Vier-Augen-Prinzip erlaeutern', 'IT', 2]],
  Produktion: [
    ['Schulungen', 'Maschinen- und Gefahrstoffunterweisung am Arbeitsplatz', 'Fuehrungskraft', 1],
    ['Arbeitsplatz', 'Persoenliche Schutzausruestung ausgeben und dokumentieren', 'Facility', -1]
  ],
  Vertrieb: [
    ['IT-Zugaenge', 'CRM-Zugang und Angebotsvorlagen freischalten', 'IT', -3],
    ['Organisation', 'Kundenliste uebergeben und Gebietszuschnitt besprechen', 'Fuehrungskraft', 2]
  ],
  Verwaltung: [['IT-Zugaenge', 'ERP- und DMS-Zugang mit passendem Rollenprofil einrichten', 'IT', -3]]
};

const AUFGABEN = [...GRUNDPAKET, ...(NACH_ABTEILUNG[m.abteilung] ?? [])];
if (m.homeoffice) AUFGABEN.push(['Arbeitsplatz', 'Homeoffice-Ausstattung und Vereinbarung zur mobilen Arbeit bereitstellen', 'Personal', -3]);
if (m.fuehrungskraft) AUFGABEN.push(['Schulungen', 'Fuehrungskraefte-Einfuehrung: Arbeitsrecht, Beurteilung, Betriebsvereinbarungen', 'Personal', 14]);

const zweiStellig = (n) => String(n).padStart(2, '0');
const datumDe = (d) => `${zweiStellig(d.getDate())}.${zweiStellig(d.getMonth() + 1)}.${d.getFullYear()}`;
const eintritt = new Date(`${m.eintritt_iso}T00:00:00`);

// Faellt eine Frist auf Samstag oder Sonntag, wird auf den Freitag davor
// vorgezogen — lieber zu frueh fertig als am Montag nicht arbeitsfaehig.
function werktag(d) {
  const x = new Date(d.getTime());
  while (x.getDay() === 0 || x.getDay() === 6) x.setDate(x.getDate() - 1);
  return x;
}

const vorgang = `ONB-${m.eintritt_iso}-${(m.nachname || 'unbekannt').toLowerCase().replace(/[^a-z]/g, '').slice(0, 10)}`;

const raus = [];
AUFGABEN.forEach((a, i) => {
  const [kategorie, aufgabe, zustaendig, versatz] = a;
  const frist = werktag(new Date(eintritt.getTime() + versatz * 86400000));
  raus.push({
    json: {
      vorgang,
      lfd_nr: i + 1,
      mitarbeiter: m.name,
      position: m.position,
      abteilung: m.abteilung,
      standort: m.standort,
      eintrittsdatum: m.eintrittsdatum,
      kategorie,
      aufgabe,
      zustaendig,
      zustaendig_mail: VERTEILER[zustaendig] || VERTEILER.Personal,
      frist: datumDe(frist),
      versatz_tage: versatz,
      // Was vor dem Eintritt faellig ist und weniger als eine Woche Zeit hat,
      // wird markiert — sonst geht es im Tagesgeschaeft unter.
      eilig: m.eilfall && versatz <= 1,
      status: 'offen',
      angelegt_am: m.gemeldet_am
    }
  });
});
return raus;

// Ein Paket je Zustaendigkeit statt einer Mail je Aufgabe. Zwoelf Einzelmails an
// die IT sind sicher der schnellste Weg, dass gar keine gelesen wird.
const aufgaben = $('Checkliste erzeugen').all().map((e) => e.json);
const gruppen = new Map();

for (const a of aufgaben) {
  if (!gruppen.has(a.zustaendig)) gruppen.set(a.zustaendig, []);
  gruppen.get(a.zustaendig).push(a);
}

const raus = [];
for (const [zustaendig, liste] of gruppen) {
  // Innerhalb des Pakets nach Frist sortieren — die Reihenfolge ist die Arbeitsliste.
  liste.sort((x, y) => x.versatz_tage - y.versatz_tage);
  const kopf = liste[0];

  const text = liste
    .map((a) => `${a.eilig ? '[EILIG] ' : ''}bis ${a.frist} — ${a.kategorie}: ${a.aufgabe}`)
    .join('\n');

  raus.push({
    json: {
      vorgang: kopf.vorgang,
      zustaendig,
      zustaendig_mail: kopf.zustaendig_mail,
      mitarbeiter: kopf.mitarbeiter,
      position: kopf.position,
      abteilung: kopf.abteilung,
      standort: kopf.standort,
      eintrittsdatum: kopf.eintrittsdatum,
      anzahl_aufgaben: liste.length,
      anzahl_eilig: liste.filter((a) => a.eilig).length,
      erste_frist: liste[0].frist,
      aufgaben_text: text
    }
  });
}
return raus;

