parameters.jsCode:
// Prueft alle laufenden Onboardings auf ueberfaellige Punkte, nicht nur den gerade
// angelegten Vorgang. Warum hier und nicht in einem eigenen Workflow: Jede Meldung
// eines neuen Mitarbeiters ist ein natuerlicher Anlass, die offene Liste einmal
// durchzugehen. Wer taeglich erinnern will, dupliziert den Workflow und ersetzt den
// Webhook durch einen Schedule Trigger.
function datumLesen(wert) {
  if (!wert) return null;
  const t = String(wert).trim();
  const de = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (de) return new Date(Number(de[3]), Number(de[2]) - 1, Number(de[1]));
  const iso = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
  return null;
}

const heute = new Date();
heute.setHours(0, 0, 0, 0);
const aktuellerVorgang = $('Checkliste erzeugen').first().json.vorgang;

const gruppen = new Map();
for (const eintrag of $input.all()) {
  const z = eintrag.json;
  const status = String(z.Status ?? '').trim().toLowerCase();
  if (status === 'erledigt' || status === 'entfaellt') continue;

  const frist = datumLesen(z.Frist);
  if (!frist || frist >= heute) continue;

  // Der eben angelegte Vorgang kann per Definition noch nicht ueberfaellig sein —
  // sonst erinnert der Workflow an Aufgaben, die er zwei Sekunden vorher erzeugt hat.
  if (z.Vorgang === aktuellerVorgang) continue;

  const tageUeberfaellig = Math.round((heute - frist) / 86400000);
  const mail = z.Zustaendig_Mail || 'HIER_MAIL_PERSONAL_EINTRAGEN';
  if (!gruppen.has(mail)) gruppen.set(mail, []);
  gruppen.get(mail).push({ ...z, tage_ueberfaellig: tageUeberfaellig });
}

if (gruppen.size === 0) {
  return [{ json: { ueberfaellig_vorhanden: false, anzahl: 0, geprueft_am: heute.toLocaleDateString('de-DE') } }];
}

const raus = [];
for (const [mail, liste] of gruppen) {
  liste.sort((x, y) => y.tage_ueberfaellig - x.tage_ueberfaellig);
  raus.push({
    json: {
      ueberfaellig_vorhanden: true,
      zustaendig: liste[0].Zustaendig,
      zustaendig_mail: mail,
      anzahl: liste.length,
      aeltester_rueckstand_tage: liste[0].tage_ueberfaellig,
      // Ab 14 Tagen Rueckstand geht eine Kopie an die Personalabteilung.
      eskalation: liste[0].tage_ueberfaellig >= 14,
      ueberfaellig_text: liste
        .map((z) => `- seit ${z.tage_ueberfaellig} Tag(en) offen (Frist ${z.Frist}) — ${z.Mitarbeiter}: ${z.Aufgabe}`)
        .join('\n'),
      geprueft_am: heute.toLocaleDateString('de-DE')
    }
  });
}
return raus;

