parameters.jsCode:
// Aus der Checkliste wird der Ablaufplan fuer die neue Person gebaut. Bewusst nur
// die Punkte, die sie selbst betreffen oder erlebt — Bestellvorgaenge und
// Sozialversicherungsmeldungen interessieren am ersten Tag niemanden.
const aufgaben = $('Checkliste erzeugen').all().map((e) => e.json);
const m = $('Stammdaten pruefen').first().json;

const SICHTBAR = ['Organisation', 'Schulungen', 'IT-Zugaenge'];
const plan = aufgaben
  .filter((a) => SICHTBAR.includes(a.kategorie) && a.versatz_tage >= 0)
  .sort((x, y) => x.versatz_tage - y.versatz_tage)
  .map((a) => {
    const wann = a.versatz_tage === 0 ? 'Erster Arbeitstag' : `ab ${a.frist}`;
    return `- ${wann}: ${a.aufgabe}`;
  })
  .join('\n');

return [{
  json: {
    ...m,
    vorgang: aufgaben[0].vorgang,
    ablaufplan: plan,
    anzahl_gesamtaufgaben: aufgaben.length
  }
}];
